import{_ as a,o as r,c as t,a2 as n}from"./chunks/framework.DyLyN3RJ.js";const h=JSON.parse('{"title":"2026-11-01 Agent Research and Competitor Intelligence","description":"Exact attribution, cancellation and recovery evidence, authentication migration and plugin/release boundaries.","frontmatter":{"title":"2026-11-01 Agent Research and Competitor Intelligence","description":"Exact attribution, cancellation and recovery evidence, authentication migration and plugin/release boundaries."},"headers":[],"relativePath":"en/runtime/daily-intelligence/2026-11-01.md","filePath":"en/runtime/daily-intelligence/2026-11-01.md","lastUpdated":1793544350000}'),i={name:"en/runtime/daily-intelligence/2026-11-01.md"};function s(o,e,l,c,d,p){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="_2026-11-01-agent-research-and-competitor-intelligence" tabindex="-1">2026-11-01 Agent Research and Competitor Intelligence <a class="header-anchor" href="#_2026-11-01-agent-research-and-competitor-intelligence" aria-label="Permalink to &quot;2026-11-01 Agent Research and Competitor Intelligence&quot;">​</a></h1><p>The key conclusion: <strong>an evaluator fix is not a new score, partial recovery is not end-to-end qualification, and plugin-view isolation is not a worker sandbox.</strong> A repository associated with Shaokun Zhang fixes exact attribution; Paperclip&#39;s full rolling workflow remains FAILED; Eigent/Orca have released deliverables while Copilot/Android retain prerelease boundaries. All CodeFlowMu/FCoP implications are pending validation.</p><h2 id="_1-failure-attribution-repository-associated-with-shaokun-zhang-fixes-exact-label-matching" tabindex="-1">1. Failure-attribution repository associated with Shaokun Zhang fixes exact label matching <a class="header-anchor" href="#_1-failure-attribution-repository-associated-with-shaokun-zhang-fixes-exact-label-matching" aria-label="Permalink to &quot;1. Failure-attribution repository associated with Shaokun Zhang fixes exact label matching&quot;">​</a></h2><p><strong>Status: MERGED #15 (2026-10-30); NO BENCHMARK RERUN</strong></p><p>Source event dates (UTC): 2026-10-30</p><p>evaluate_accuracy in Agents_Failure_Attribution now compares agent and step labels by exact equality, avoiding substring false positives such as agent_1/agent_10 and 1/10. Upstream ran two regressions on a self-authored synthetic JSON fixture, not the benchmark dataset, models or real traces. No corrected benchmark score or new paper is established. This is a contributor&#39;s PR, not attributed as the researcher&#39;s new personal result.</p><p>Pending FCoP lead: localization accuracy needs testable label semantics. Discuss affected historical results, a pinned-data/model rerun, and separate versus joint agent/step accuracy.</p><p>Original sources: <a href="https://github.com/ag2ai/Agents_Failure_Attribution/pull/15" target="_blank" rel="noreferrer">Evidence 1</a></p><h2 id="_2-codex-main-retains-incomplete-attempts-as-evidence-and-pins-identity-during-credential-rotation" tabindex="-1">2. Codex main retains incomplete attempts as evidence and pins identity during credential rotation <a class="header-anchor" href="#_2-codex-main-retains-incomplete-attempts-as-evidence-and-pins-identity-during-credential-rotation" aria-label="Permalink to &quot;2. Codex main retains incomplete attempts as evidence and pins identity during credential rotation&quot;">​</a></h2><p><strong>Status: MERGED #58456/#58251/#58343; STABLE STILL 0.166.0</strong></p><p>Source event dates (UTC): 2026-10-30</p><p>#58456 retains incomplete terminal-response items in failed traces, deduplicated by ID, without streaming, dispatching or caching them for continuation; debug omits payloads. #58251 reloads remote-executor credentials before requests, pins account/user/workspace/mode and coordinates atomic concurrent refresh/logout; a generation with unknown refresh outcome is not reused. #58343 persists fallback rotations when the keyring is unreadable. Stable remains 0.166.0; stable-package inclusion is unverified.</p><p>Pending lead: observed attempts are not executions, and rotating tokens must not rotate identity. Discuss attempted/executed trace semantics and logout versus atomic replacement races.</p><p>Original sources: <a href="https://github.com/openai/codex/pull/58456" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/openai/codex/pull/58251" target="_blank" rel="noreferrer">Evidence 2</a> · <a href="https://github.com/openai/codex/pull/58343" target="_blank" rel="noreferrer">Evidence 3</a></p><h2 id="_3-openai-agents-sdk-confines-skill-destination-writes-to-docker-and-improves-payload-free-stream-diagnostics" tabindex="-1">3. OpenAI Agents SDK confines skill destination writes to Docker and improves payload-free stream diagnostics <a class="header-anchor" href="#_3-openai-agents-sdk-confines-skill-destination-writes-to-docker-and-improves-payload-free-stream-diagnostics" aria-label="Permalink to &quot;3. OpenAI Agents SDK confines skill destination writes to Docker and improves payload-free stream diagnostics&quot;">​</a></h2><p><strong>Status: JS #2091 / PYTHON #5457 MERGED; RELEASE NOT VERIFIED</strong></p><p>Source event dates (UTC): 2026-10-30</p><p>JS #2091 copies local-directory skills through Docker archive copy on stdin instead of writing container destinations via the host filesystem. It preserves bytes, permissions and ownership and rejects destinations in live-created mounts inaccessible to archive copy. Python #5457 adds request/response IDs, event count and last type for missing response.completed without prompt/output payloads or retry changes; it does not fix interruption itself. Documented baseline full-suite failures are not called a clean full pass.</p><p>Pending lead: installation, host and container boundaries differ; diagnostics are not recovery. Discuss concurrent directory swaps, mount exceptions and correlated failures without payload leakage.</p><p>Original sources: <a href="https://github.com/openai/openai-agents-js/pull/2091" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/openai/openai-agents-python/pull/5457" target="_blank" rel="noreferrer">Evidence 2</a></p><h2 id="_4-claude-code-2-1-316-releases-layered-policy-pooled-budgets-and-process-stop-lifecycle-fixes" tabindex="-1">4. Claude Code 2.1.316 releases layered policy, pooled budgets and process/Stop lifecycle fixes <a class="header-anchor" href="#_4-claude-code-2-1-316-releases-layered-policy-pooled-budgets-and-process-stop-lifecycle-fixes" aria-label="Permalink to &quot;4. Claude Code 2.1.316 releases layered policy, pooled budgets and process/Stop lifecycle fixes&quot;">​</a></h2><p><strong>Status: RELEASED 2026-10-31</strong></p><p>Source event dates (UTC): 2026-10-31</p><p>The gateway adds layered merging of all matching policies and pooled monthly group budgets on top of member limits. Fixes cover orphan shell commands after self-exit on macOS/Linux, PowerShell syntax preventing exit-2 hook blocks, managed allow lists regaining default exceptions, and cloud tasks not failing on no safety verdict. Self-hosted runners no longer answer pre-Stop queued messages after process replacement. Server-managed Team/Enterprise settings apply without approval prompts; unverifiable stored copies are refused.</p><p>Pending lead: policy composition, child termination and durable Stop must hold across restart. Discuss no-verdict states, pooled/personal budget intersections and separate Windows process-tree guarantees.</p><p>Original sources: <a href="https://github.com/anthropics/claude-code/releases/tag/v2.1.316" target="_blank" rel="noreferrer">Evidence 1</a></p><h2 id="_5-ag2-waits-for-command-cancellation-and-retains-full-final-tool-batches-for-replay" tabindex="-1">5. AG2 waits for command cancellation and retains full final-tool batches for replay <a class="header-anchor" href="#_5-ag2-waits-for-command-cancellation-and-retains-full-final-tool-batches-for-replay" aria-label="Permalink to &quot;5. AG2 waits for command cancellation and retains full final-tool batches for replay&quot;">​</a></h2><p><strong>Status: MERGED #3512/#3562 (2026-11-01); RELEASE NOT VERIFIED</strong></p><p>Source event dates (UTC): 2026-11-01</p><p>#3512 waits for termination/reaping on cancel, timeout and close; queued commands not yet started are never launched. POSIX uses a separate process group to stop shell descendants; Windows kills only the direct process, not a guaranteed whole tree. #3562 saves the complete finished tool batch before a final=True forced reply, including later sibling results/errors, with provider-history deduplication. Eleven mapper checks used no live provider API.</p><p>Pending lead: cancellation acknowledgement must not precede stopped effects, and final replies must not drop parallel results. Discuss Windows descendants, repeated cancellation and old persisted histories.</p><p>Original sources: <a href="https://github.com/ag2ai/ag2/pull/3512" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/ag2ai/ag2/pull/3562" target="_blank" rel="noreferrer">Evidence 2</a></p><h2 id="_6-langgraph-1-2-19-and-sdk-0-4-11-release-stream-fixes-with-trace-policy-boundaries" tabindex="-1">6. LangGraph 1.2.19 and SDK 0.4.11 release stream fixes with trace-policy boundaries <a class="header-anchor" href="#_6-langgraph-1-2-19-and-sdk-0-4-11-release-stream-fixes-with-trace-policy-boundaries" aria-label="Permalink to &quot;6. LangGraph 1.2.19 and SDK 0.4.11 release stream fixes with trace-policy boundaries&quot;">​</a></h2><p><strong>Status: RELEASED 2026-10-30</strong></p><p>Source event dates (UTC): 2026-10-30</p><p>SDK 0.4.11 explicitly releases earlier reconnect backoff, missing Last-Event-ID warnings and cross-chunk data/cursor fixes; no cursor still means no lossless replay guarantee. Version 1.2.19 fixes graph/task message/tool namespaces and trace_policy altering business streams: BaseTracer gets processed payloads, other handlers real payloads. Non-BaseTracer integrations such as Langfuse/MLflow also get real payloads, and processor errors may still record raw data; this is not global redaction.</p><p>Pending FCoP lead: separate business streaming, trace trimming and privacy. Discuss custom-handler contracts, redaction failure behavior and recording reconnect gaps in verification.</p><p>Original sources: <a href="https://github.com/langchain-ai/langgraph/releases/tag/1.2.19" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/langchain-ai/langgraph/releases/tag/sdk%3D%3D0.4.11" target="_blank" rel="noreferrer">Evidence 2</a> · <a href="https://github.com/langchain-ai/langgraph/pull/9486" target="_blank" rel="noreferrer">Evidence 3</a></p><h2 id="_7-phoenix-21-0-0-materially-changes-binding-authentication-and-credential-migration" tabindex="-1">7. Phoenix 21.0.0 materially changes binding, authentication and credential migration <a class="header-anchor" href="#_7-phoenix-21-0-0-materially-changes-binding-authentication-and-credential-migration" aria-label="Permalink to &quot;7. Phoenix 21.0.0 materially changes binding, authentication and credential migration&quot;">​</a></h2><p><strong>Status: RELEASED 2026-10-30; MIGRATION DOCUMENT READ AT RELEASE TAG</strong></p><p>Source event dates (UTC): 2026-10-30</p><p>Binding defaults to loopback; with auth unset, non-loopback enables auth and loopback disables it, so the non-loopback Docker image enables auth by default. Notebooks now honor auth settings. PHOENIX_SECRET becomes optional, but without it a database holder can decrypt stored credentials; setting/changing it makes old credentials unreadable. Replacing an unchanged default-admin password has documented replica-stop/cache boundaries for revocation; API keys remain valid. Browser logout no longer equals OAuth2 logout.</p><p>Pending lead: safe defaults, at-rest protection and session revocation are separate. Evaluate upgrades against the release-pinned migration document, not just a toggle. Discuss multi-replica revocation evidence, secret rotation recovery and API-key cleanup.</p><p>Original sources: <a href="https://github.com/Arize-ai/phoenix/releases/tag/arize-phoenix-v21.0.0" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/Arize-ai/phoenix/blob/arize-phoenix-v21.0.0/MIGRATION.md" target="_blank" rel="noreferrer">Evidence 2</a></p><h2 id="_8-mcp-merges-built-in-typescript-telemetry-and-a-security-routing-charter" tabindex="-1">8. MCP merges built-in TypeScript telemetry and a security-routing charter <a class="header-anchor" href="#_8-mcp-merges-built-in-typescript-telemetry-and-a-security-routing-charter" aria-label="Permalink to &quot;8. MCP merges built-in TypeScript telemetry and a security-routing charter&quot;">​</a></h2><p><strong>Status: MERGED SDK #3115 / SPEC #3331; SDK RELEASE NOT VERIFIED</strong></p><p>Source event dates (UTC): 2026-10-31</p><p>Client/Server/McpServer emit request/notification spans and duration metrics, propagating context in params._meta. An app&#39;s registered OTEL SDK receives them; without one, calls are no-op and messages unchanged, with a per-instance off switch. Tool/prompt arguments and results are not recorded; a peer dependency shares the app&#39;s API. The Security IG charter implements an earlier decision to triage/validate and route to owners through asynchronous discussion and agenda-driven forums; it is not a new wire-security mechanism.</p><p>Pending lead: trace identity is not authorization, and security routing is not remediation. Discuss cross-process context, duplicate instrumentation and unchanged messages when telemetry is off.</p><p>Original sources: <a href="https://github.com/modelcontextprotocol/typescript-sdk/pull/3115" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/modelcontextprotocol/modelcontextprotocol/pull/3331" target="_blank" rel="noreferrer">Evidence 2</a></p><h2 id="_9-openhands-sdk-loads-user-hooks-and-traces-decision-model-calls" tabindex="-1">9. OpenHands SDK loads user hooks and traces decision-model calls <a class="header-anchor" href="#_9-openhands-sdk-loads-user-hooks-and-traces-decision-model-calls" aria-label="Permalink to &quot;9. OpenHands SDK loads user hooks and traces decision-model calls&quot;">​</a></h2><p><strong>Status: MERGED #5734/#6068; LATEST RELEASE STILL 1.59.0</strong></p><p>Source event dates (UTC): 2026-10-30 / 2026-10-31</p><p>POST /api/hooks gains independent project/user source flags, both defaulting on, with project handlers first. The same file is read once; an invalid source warns/skips while retaining the other, not mandatory-policy fail-closed. DecisionModel adds SDK retries, metrics, exception handling and per-attempt spans for classifier-style questions. Sensitive state is omitted, but questions and answers are recorded. Release inclusion remains unverified.</p><p>Engel Nyst (enyst) remains directly involved in the user-hooks merge. Pending lead: hook presence, loading and enforcement differ, and telemetry fields need review. Discuss load-failure policy levels, merge order and sensitive question/answer content.</p><p>Original sources: <a href="https://github.com/OpenHands/software-agent-sdk/pull/5734" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/OpenHands/software-agent-sdk/pull/6068" target="_blank" rel="noreferrer">Evidence 2</a></p><h2 id="_10-google-adk-avoids-effects-before-rejected-writes-and-excludes-thoughts-from-memory" tabindex="-1">10. Google ADK avoids effects before rejected writes and excludes thoughts from memory <a class="header-anchor" href="#_10-google-adk-avoids-effects-before-rejected-writes-and-excludes-thoughts-from-memory" aria-label="Permalink to &quot;10. Google ADK avoids effects before rejected writes and excludes thoughts from memory&quot;">​</a></h2><p><strong>Status: COMMITTED ON MAIN; RELEASE NOT VERIFIED</strong></p><p>Source event dates (UTC): 2026-10-30 / 2026-10-31</p><p>write_file validates type and encodes UTF-8 before making directories/opening files, so invalid content no longer truncates existing bytes. FileArtifactService lists only names with a published version, excluding rejected/interrupted first saves. Redis create claims the session via SET NX before touching shared app/user state, so duplicate rejection does not overwrite it. Memory Bank/Firestore filter thought parts; Firestore also filters old documents on reads, not physical historical erasure.</p><p>Pending FCoP lead: validate before effects; a directory is not publication; filtering reads is not erasure. Discuss atomicity of later shared-state failures, cancelled first saves and old-memory cleanup evidence.</p><p>Original sources: <a href="https://github.com/google/adk-python/commit/611b8e7cc22008146c9e23587a81580424410477" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/google/adk-python/commit/2cabbddf1199f996e6e7e9040341eaecfb4add80" target="_blank" rel="noreferrer">Evidence 2</a> · <a href="https://github.com/google/adk-python/commit/c501d8eda44d386847a23a9599ce0d785009b8ec" target="_blank" rel="noreferrer">Evidence 3</a> · <a href="https://github.com/google/adk-python/commit/af371b7236c87bad36957e5f691b350c513e6bb2" target="_blank" rel="noreferrer">Evidence 4</a> · <a href="https://github.com/google/adk-python/commit/4fae7b75c9c9d41bc2ee3ac79001b87f005be6ab" target="_blank" rel="noreferrer">Evidence 5</a></p><h2 id="_11-paperclip-merges-volume-free-rolling-handoff-but-full-qualification-remains-failed" tabindex="-1">11. Paperclip merges volume-free rolling handoff but full qualification remains FAILED <a class="header-anchor" href="#_11-paperclip-merges-volume-free-rolling-handoff-but-full-qualification-remains-failed" aria-label="Permalink to &quot;11. Paperclip merges volume-free rolling handoff but full qualification remains FAILED&quot;">​</a></h2><p><strong>Status: MERGED #18526/#18543; FULL WORKFLOW FAILED; RELEASE NOT VERIFIED</strong></p><p>Source event dates (UTC): 2026-11-01</p><p>The rolling lane uses independent A/B/C homes, routes after readiness, drains/deletes predecessors and preserves Stop across lease release/expiry, allowing fenced original-execution cleanup without a new turn. The latest real test records two empty-home replacements, 523 reads and 53 verified saves with no probe failures, and the active execution survives/completes once. Later continuation resets the native/provider session and the public run row lacks its terminal contract, so the full workflow remains FAILED, not qualified zero-downtime production.</p><p>High learning value and risk; raise main-radar recovery attention while keeping maturity limited. Pending FCoP lead: successful IO cannot override end-to-end identity/terminal failure. Discuss same-session continuation, read-only oracles and old-controller shutdown attribution.</p><p>Original sources: <a href="https://github.com/paperclipai/paperclip/pull/18526" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/paperclipai/paperclip/pull/18543" target="_blank" rel="noreferrer">Evidence 2</a></p><h2 id="_12-paperclip-requires-migration-receipts-and-verified-file-restoration-before-publication" tabindex="-1">12. Paperclip requires migration receipts and verified file restoration before publication <a class="header-anchor" href="#_12-paperclip-requires-migration-receipts-and-verified-file-restoration-before-publication" aria-label="Permalink to &quot;12. Paperclip requires migration receipts and verified file restoration before publication&quot;">​</a></h2><p><strong>Status: MERGED #18529/#18531; HOSTED ENROLLMENT NOT QUALIFIED</strong></p><p>Source event dates (UTC): 2026-11-01</p><p>A standalone maintenance entry starts no business routes/execution workers, requires stopped writers and paged agent-file/evidence/skill migration with shared-byte verification. It preserves the original decision signing key and exports only after matching-attempt success, never a replacement key. Hosted Cloud transition is a separate private change. Folder restore uses at most eight streams, settles cancelled siblings before cleanup and verifies size/hash before publication. Upstream&#39;s delayed 1,024-file case moves from a 30-second failure to 4.180-second pass, not universal production proof.</p><p>High learning value, medium-high risk; increase main-radar migration/delivery attention. Pending lead: original signing identity and exact receipts precede detachment; copied files are insufficient. Discuss process exit after timeout, key-export boundaries and partial-restore retries.</p><p>Original sources: <a href="https://github.com/paperclipai/paperclip/pull/18529" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/paperclipai/paperclip/pull/18531" target="_blank" rel="noreferrer">Evidence 2</a></p><h2 id="_13-paperclip-persists-usage-before-ack-and-prevents-a-run-from-clearing-its-own-lock" tabindex="-1">13. Paperclip persists usage before ACK and prevents a run from clearing its own lock <a class="header-anchor" href="#_13-paperclip-persists-usage-before-ack-and-prevents-a-run-from-clearing-its-own-lock" aria-label="Permalink to &quot;13. Paperclip persists usage before ACK and prevents a run from clearing its own lock&quot;">​</a></h2><p><strong>Status: MERGED #18354/#18411; RELEASE NOT VERIFIED</strong></p><p>Source event dates (UTC): 2026-10-30 / 2026-10-31</p><p>Runner usage receipts are accepted into Postgres before transport ACK; replay preserves the source receipt and one charge, while missing usage stays pending. A native run&#39;s generic PATCH of its own task status previously cleared its execution lock and broke subsequent tools/finish. It now returns 409 before commit and directs finish/block reporting through the status arbiter, without banning legitimate human/other workflow updates.</p><p>High learning value and risk; increase accounting/authority weight. Pending FCoP lead: receipt is not persistence and reporting an outcome is not authority to write status. Discuss lost commit responses, conflicting replay and pending-budget visibility.</p><p>Original sources: <a href="https://github.com/paperclipai/paperclip/pull/18354" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/paperclipai/paperclip/pull/18411" target="_blank" rel="noreferrer">Evidence 2</a></p><h2 id="_14-eigent-1-0-7-advances-from-version-preparation-to-published-installers" tabindex="-1">14. Eigent 1.0.7 advances from version preparation to published installers <a class="header-anchor" href="#_14-eigent-1-0-7-advances-from-version-preparation-to-published-installers" aria-label="Permalink to &quot;14. Eigent 1.0.7 advances from version preparation to published installers&quot;">​</a></h2><p><strong>Status: RELEASED 2026-10-30</strong></p><p>Source event dates (UTC): 2026-10-30</p><p>Previously only a version bump was merged; now the Release publishes Windows Setup EXE, macOS DMG/ZIP, Linux AppImage and updater metadata. It explicitly includes Run now, missed-execution recovery, one-window background ownership, local-time scheduling and preserved login/Space after update. Approval targets, reloadable questions, confirmed memory changes and upgrade/BYOK options are listed. The earlier Web Locks fallback limitation remains; once-only wording is not universal exactly-once.</p><p>High learning value, medium-high risk; raise delivery maturity on the main radar. Pending lead: published installers are separate from verified upgrade/recovery. Discuss owner failover, delivery windows and pending approvals across updates.</p><p>Original sources: <a href="https://github.com/eigent-ai/eigent/releases/tag/v1.0.7" target="_blank" rel="noreferrer">Evidence 1</a></p><h2 id="_15-orca-1-4-245-enables-plugins-and-exposes-an-important-account-history-sharing-default" tabindex="-1">15. Orca 1.4.245 enables plugins and exposes an important account-history sharing default <a class="header-anchor" href="#_15-orca-1-4-245-enables-plugins-and-exposes-an-important-account-history-sharing-default" aria-label="Permalink to &quot;15. Orca 1.4.245 enables plugins and exposes an important account-history sharing default&quot;">​</a></h2><p><strong>Status: DESKTOP 1.4.245 RELEASED; ANDROID 0.0.61 PRE-RELEASE</strong></p><p>Source event dates (UTC): 2026-10-30</p><p>Desktop publishes Windows EXE, macOS and Linux packages. Plugins are on by default with review/consent before code execution; approved workers have full computer access, not a worker sandbox. New terminals use the new host while old hosts live on. Share Codex history across accounts defaults on; disabling stops new sharing, not old-data removal, and old remote hosts need upgrade. Android 0.0.61 is a prerelease with APK/sha256, merge completion, dictation through reconnect and connected-only alerts without push.</p><p>High learning value, medium-high risk; retain second-circle priority for delivery, mobile and credential/history boundaries. Pending lead: account switching does not imply history isolation. Discuss sharing migration/cleanup, old hosts and precise plugin-consent scope.</p><p>Original sources: <a href="https://github.com/stablyai/orca/releases/tag/v1.4.245" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/stablyai/orca/releases/tag/mobile-android-v0.0.61" target="_blank" rel="noreferrer">Evidence 2</a></p><h2 id="_16-orca-main-defaults-plugin-view-isolation-on-without-sandboxing-workers" tabindex="-1">16. Orca main defaults plugin-view isolation on, without sandboxing workers <a class="header-anchor" href="#_16-orca-main-defaults-plugin-view-isolation-on-without-sandboxing-workers" aria-label="Permalink to &quot;16. Orca main defaults plugin-view isolation on, without sandboxing workers&quot;">​</a></h2><p><strong>Status: MERGED #36812/#36821; RELEASE INCLUSION NOT VERIFIED</strong></p><p>Source event dates (UTC): 2026-11-01</p><p>Plugin camera/microphone/fullscreen/pointer-lock requests are rejected using creation-time frame identity/ancestry, not mutable window.name. Desktop views default to per-plugin isolated process/storage/network-blocked sessions with main-process escape switches; browser/serve clients retain iframes. This later main work is not verified in a released build, and view isolation does not replace native workers&#39; full-access consent boundary.</p><p>High learning value, medium-high risk; increase second-circle UI/worker separation attention. Pending lead: rendering, network and execution authority differ. Discuss nested frames, fallback clients and main-process API authority matrices.</p><p>Original sources: <a href="https://github.com/stablyai/orca/pull/36812" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/stablyai/orca/pull/36821" target="_blank" rel="noreferrer">Evidence 2</a></p><h2 id="_17-paradev-devs-adds-scheduled-event-routines-and-message-header-forgery-protection" tabindex="-1">17. Paradev Devs adds scheduled/event routines and message-header forgery protection <a class="header-anchor" href="#_17-paradev-devs-adds-scheduled-event-routines-and-message-header-forgery-protection" aria-label="Permalink to &quot;17. Paradev Devs adds scheduled/event routines and message-header forgery protection&quot;">​</a></h2><p><strong>Status: MERGED #9134/#9040; RELEASE NOT VERIFIED</strong></p><p>Source event dates (UTC): 2026-10-30</p><p>Devs gain one-off, recurring, channel and provider-event routines as main-session turns with requester/reply target. They reuse the minute reconciler, run at most hourly, let Devs pause but only people delete, and remain distinct from Automations. #9040 escapes body message tags and attributes that could forge trusted sender/reply headers. Structured provenance and external-untrusted marking remain a target, not complete prompt-injection defense.</p><p>High learning value and risk; increase proactive digital-employee attention. Pending lead: proactive turns must retain requester/source authority. Discuss routine identity/rate limits, redelivery deduplication and structured provenance replacing text headers.</p><p>Original sources: <a href="https://github.com/ParadevAI/Paradev/pull/9134" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/ParadevAI/Paradev/pull/9040" target="_blank" rel="noreferrer">Evidence 2</a></p><h2 id="_18-paradev-registers-clients-for-expanded-scopes-while-binding-old-grants-to-their-original-client" tabindex="-1">18. Paradev registers clients for expanded scopes while binding old grants to their original client <a class="header-anchor" href="#_18-paradev-registers-clients-for-expanded-scopes-while-binding-old-grants-to-their-original-client" aria-label="Permalink to &quot;18. Paradev registers clients for expanded scopes while binding old grants to their original client&quot;">​</a></h2><p><strong>Status: MERGED #9203; RELEASE NOT VERIFIED; MIT DRAFT UNCHANGED</strong></p><p>Source event dates (UTC): 2026-10-31</p><p>A dynamically registered client was reused forever per issuer/redirect, causing provider rejection after scope growth. New grants now select a scope-covering client or register one; signed state/connection records pin the exact client. Refresh must use that client, with missing rows requiring reauth rather than a new client for an old token. Legacy unbound grants retain the oldest-client compatibility rule. Rechecking #9107 confirms OPEN/DRAFT and main ELv2, with no new effective license change.</p><p>High learning value, medium-high risk; increase identity/integration maturity attention while leaving license classification unchanged. Pending lead: bind requested scope, registered client and issued grant separately. Discuss concurrent registration, legacy ownership and scope reduction.</p><p>Original sources: <a href="https://github.com/ParadevAI/Paradev/pull/9203" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/ParadevAI/Paradev/pull/9107" target="_blank" rel="noreferrer">Evidence 2</a> · <a href="https://github.com/ParadevAI/Paradev/blob/main/LICENSE.md" target="_blank" rel="noreferrer">Evidence 3</a></p><h2 id="_19-orkas-fences-stale-oauth-replies-and-preserves-edits-during-cross-library-moves" tabindex="-1">19. Orkas fences stale OAuth replies and preserves edits during cross-library moves <a class="header-anchor" href="#_19-orkas-fences-stale-oauth-replies-and-preserves-edits-during-cross-library-moves" aria-label="Permalink to &quot;19. Orkas fences stale OAuth replies and preserves edits during cross-library moves&quot;">​</a></h2><p><strong>Status: MERGED #142/#144; RELEASE NOT VERIFIED</strong></p><p>Source event dates (UTC): 2026-10-31</p><p>Late cancelled/superseded token exchanges cannot clear/reject a new flow; only the active exchange settles success/failure. Cross-library moves check bounded revisions, file identity and nanosecond change times before source removal, avoid symlinks and refuse unavailable metadata; partial deletion keeps the full destination. Final checking does not yield to app writers, but external-process OS races remain. Library local evidence is macOS, not equivalent Windows verification.</p><p>High learning value, medium risk; increase main-radar preservation/authorization attention. Pending lead: copied bytes do not authorize deletion and a browser callback is not current-flow evidence. Discuss external writers, recovery entry points and late-success credential disposal.</p><p>Original sources: <a href="https://github.com/Orkas-AI/Orkas/pull/142" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/Orkas-AI/Orkas/pull/144" target="_blank" rel="noreferrer">Evidence 2</a></p><h2 id="_20-copilot-cli-prereleases-improve-shutdown-records-mcp-startup-and-config-preservation" tabindex="-1">20. Copilot CLI prereleases improve shutdown records, MCP startup and config preservation <a class="header-anchor" href="#_20-copilot-cli-prereleases-improve-shutdown-records-mcp-startup-and-config-preservation" aria-label="Permalink to &quot;20. Copilot CLI prereleases improve shutdown records, MCP startup and config preservation&quot;">​</a></h2><p><strong>Status: v1.0.106-1 / v1.0.106-2 PRE-RELEASE, NOT STABLE</strong></p><p>Source event dates (UTC): 2026-10-31 / 2026-11-01</p><p>-1 waits for shutdown usage/code-change records on Ctrl+C/signals in headless runs and rejects invalid session.resume parameters without crashing the server. -2 applies one connection timeout to silent HTTP MCP startup, preserves symlinked MCP config targets, reports skill-refresh failures promptly and foregrounds an existing background session without duplicate display. Both GitHub entries have prerelease=true, not stable delivery.</p><p>Pending lead: exit needs completed usage/change receipts and config saves must preserve path structure. Discuss force-kill versus graceful exit, MCP timeout budgets and concurrent symlink updates.</p><p>Original sources: <a href="https://github.com/github/copilot-cli/releases/tag/v1.0.106-1" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/github/copilot-cli/releases/tag/v1.0.106-2" target="_blank" rel="noreferrer">Evidence 2</a></p><h2 id="cross-project-signals-and-classification" tabindex="-1">Cross-project signals and classification <a class="header-anchor" href="#cross-project-signals-and-classification" aria-label="Permalink to &quot;Cross-project signals and classification&quot;">​</a></h2><ul><li><strong>Evidence precision bounds conclusions:</strong> exact-label fixes do not rerun a benchmark; attempted calls in failed traces are not executions; partial rolling passes cannot override a FAILED full workflow.</li><li><strong>Cancellation/rejection must respect effect boundaries:</strong> AG2 waits for termination, ADK validates before opening files, and Paperclip persists before ACK, protecting different stages.</li><li><strong>Identity survives cross-layer recovery:</strong> credential rotation, OAuth client/grant, status arbitration, durable Stop and original signing keys cannot silently change owners.</li><li><strong>Visibility is not redaction or isolation:</strong> retain LangGraph non-tracer raw payload, DecisionModel question/answer fields, Orca view/worker separation and history-sharing defaults.</li><li><strong>Release, enablement and maturity differ:</strong> Eigent/Orca desktop are released; Android APK and Copilot CLI are prereleases; main isolation/hooks/copy changes are not assumed released.</li></ul><p>This is information collection, classification and reporting only: 20 groups, local engineering experiments 0, articles 0, formal development reviews 0, external comments/messages 0. Upstream tests, production accounts and synthetic regressions retain their scope; every CodeFlowMu/FCoP implication is pending validation. Beads SQL-classification hardening is retained as background: the pinned supported Dolt already rejects the relevant SELECT writers, so it is not reported as a confirmed exploitable write bypass. Ordinary UI, marketing, test cleanup and low-increment releases are not separately listed.</p><h2 id="dual-source-checks-deduplication-and-coverage-gaps" tabindex="-1">Dual-source checks, deduplication and coverage gaps <a class="header-anchor" href="#dual-source-checks-deduplication-and-coverage-gaps" aria-label="Permalink to &quot;Dual-source checks, deduplication and coverage gaps&quot;">​</a></h2><p>Actual start: 2026-11-01 22:26:48 Asia/Shanghai. Trusted per-source baseline: 2026-10-30 10:03:00, a main window of about 60 hours 24 minutes. No successful October 31 run record was found. This run checks that gap without creating an empty backdated report or calling October 30/31 events November 1 events. Original event dates are shown per group. Unfinished feeds retain older pending windows and prior reports, including October 30, provide deduplication.</p><p>The latest-main Registry was first read through connected GitHub tools: 47 people, blob 8d97df65269aa2b4accd1366d1b71319f99c6efd. Relationships remain many-to-many. The six governance subjects retain their boundaries; the new failure-attribution fix is a contributor change in Shaokun Zhang&#39;s related repository, not his new paper. bulbasaur-skill-cli is not the official AGENTSAFE artifact. The listed Zhao repositories were checked incrementally and at default heads, with no new code confirmed. Audit Commons&#39; visible latest remains October 27 and is historical. Aegis changes mainly marketing presentation/demos, not a newly completed benchmark.</p><p>There are 88 targets including 32 competitors: 996 incremental commit records across 30 changed targets; 57 accessible zero-increment heads were checked separately. The 7,078 raw PR/Issue records have separate unique_count values because dynamic pages can duplicate. Important PRs, Phoenix&#39;s release-tag MIGRATION.md, Paradev main LICENSE.md and redirect repository ID 1080370450 were separately checked. Superset retains its monitoring name while accessing verified ParadevAI/Paradev. Author/merger evidence is retained: OpenHands enyst and Paperclip cryppadotta/nickyleach/devinfoley directly participate in merges; unverified account/person mappings are not inferred.</p><p>Gaps: Codex, Claude Code and Orca PR/Issue feeds remain unfinished after 12 pages each. All three TSA feeds return 404, not proof of deletion/privacy. Releases are mainly latest ten, Codex latest three, plus a stable lookup; Codex remains 0.166.0 and the SDK 1.59.0. Discussions, roadmaps, every architecture file and every license are not exhaustive. Only complete successful queries advance their own watermark; partial, failed and unchecked are not no-change. The global full-coverage watermark remains null. Broad events retain necessary IDs/URLs/SHAs/states/times locally, with full selected PR/commit evidence, not all discussion bodies.</p><p>Public web/social is a separate source type: current 47 names were searched in 12 groups plus identifiable person/X queries, with direct Cursor changelog/blog and Audit Commons reads. No reliably timed personal post within the window was confirmed. Search misses are not exhaustive X coverage and ambiguous names are not attributed. Cursor&#39;s visible latest changelog remains October 20. Primary GitHub engineering evidence can stand independently; two GitHub links are not two source types.</p><h2 id="github-archive-and-website-delivery" tabindex="-1">GitHub archive and website delivery <a class="header-anchor" href="#github-archive-and-website-delivery" aria-label="Permalink to &quot;GitHub archive and website delivery&quot;">​</a></h2><p>Both languages preserve the same 20 groups, states, 43 sources and judgments. Only the dated reports and two indexes are written through connected GitHub tools, keeping unique descending dates, fixed entry points and index structure. Existing-site builds use fresh source and non-force gh-pages publication, preserving layout, snapshots, translation caches and other content. Four-file readback, main/publication concurrency checks, matching Pages success and actual bilingual clicks are recorded locally; this paragraph does not preclaim deployment. Protected Research Runtime business facts, Scheduler, candidates/articles/scorecards/lifecycle remain unchanged.</p>',133)])])}const g=a(i,[["render",s]]);export{h as __pageData,g as default};
